 class RealCache extends RagEmbeddingClient {
  final RagEmbeddingClient real;final Map<String,double[]> cache=new HashMap<>();int calls,inputs,reused;
  RealCache(RagEmbeddingClient real,ObjectMapper mapper){super(false,"","","",mapper);this.real=real;}
  @Override public boolean isConfigured(){return real.isConfigured();}@Override public boolean isRequested(){return true;}
  @Override public String fingerprint(){return real.fingerprint();}@Override public String modelName(){return real.modelName();}
  void prime(List<String> values){var result=real.embed(values);calls++;inputs+=values.size();for(int i=0;i<values.size();i++)cache.put(values.get(i),result.get(i));}
  @Override public List<double[]> embed(List<String> values){var missing=values.stream().filter(s->!cache.containsKey(s)).distinct().toList();if(!missing.isEmpty())prime(missing);reused+=values.size()-missing.size();return values.stream().map(s->cache.get(s).clone()).toList();}
 }
